INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (572, 1, 'MASQUERADE 대상 대역', '`/tmp/nat.log` 는 NAT 장비에서 `iptables -t nat -S` 로 뽑은 규칙입니다. 내부 서버가 외부로 나갈 때 출발지 주소를 장비의 바깥 주소로 바꾸는 규칙이 `POSTROUTING` 체인의 `MASQUERADE` 입니다. **이 규칙이 적용되는 출발지 대역**(`-s` 값)을 `/tmp/inside.txt` 에 저장하세요. (값만)', '`MASQUERADE` 로 끝나는 줄에서 `-s` 다음 값입니다.', 'cat /tmp/nat.log
grep -- ''-j MASQUERADE'' /tmp/nat.log | grep -o -- ''-s [0-9./]*'' | awk ''{print $2}'' > /tmp/inside.txt
cat /tmp/inside.txt

# 내부 대역의 사설 주소는 외부에서 되돌아올 수 없어 장비의 바깥 주소로 바꿔 나간다. 응답이 오면 conntrack 이 기억해 둔 원래 주소로 되돌린다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.conf\\ncat > /tmp/nat.log <<''EOF''\\n-P PREROUTING ACCEPT\\n-P INPUT ACCEPT\\n-P OUTPUT ACCEPT\\n-P POSTROUTING ACCEPT\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 8443 -j DNAT --to-destination 192.0.2.20:443\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 2222 -j DNAT --to-destination 192.0.2.21:22\\n-A POSTROUTING -s 192.0.2.0/24 -o eth0 -j MASQUERADE\\nEOF\\ncat > /tmp/sysctl.log <<''EOF''\\nnet.ipv4.ip_forward = 0\\nnet.ipv4.conf.all.rp_filter = 1\\nEOF\\ncat > /tmp/conn.log <<''EOF''\\ntcp      6 431999 ESTABLISHED src=203.0.113.77 dst=203.0.113.10 sport=51000 dport=8443 src=192.0.2.20 dst=203.0.113.77 sport=443 dport=51000 [ASSURED] mark=0 use=1\\ntcp      6 431998 ESTABLISHED src=203.0.113.88 dst=203.0.113.10 sport=51111 dport=2222 src=192.0.2.21 dst=203.0.113.88 sport=22 dport=51111 [ASSURED] mark=0 use=1\\ntcp      6 118 TIME_WAIT src=192.0.2.30 dst=198.51.100.50 sport=40000 dport=443 src=198.51.100.50 dst=203.0.113.10 sport=443 dport=40000 [ASSURED] mark=0 use=1\\ntcp      6 2 SYN_SENT src=192.0.2.31 dst=198.51.100.60 sport=40001 dport=443 [UNREPLIED] src=198.51.100.60 dst=203.0.113.10 sport=443 dport=40001 mark=0 use=1\\ntcp      6 431990 ESTABLISHED src=192.0.2.32 dst=198.51.100.70 sport=40002 dport=443 src=198.51.100.70 dst=203.0.113.10 sport=443 dport=40002 [ASSURED] mark=0 use=1\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/inside.txt)\\" = 192.0.2.0/24 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "192.0.2.0/24 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/inside.txt)\\" = 192.0.2.0/24 ]"]}]', '[{"title": "iptables 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/iptables.8.html"}, {"title": "Netfilter NAT 안내", "url": "https://www.netfilter.org/documentation/HOWTO/NAT-HOWTO.html"}]'),
  (572, 2, '포트포워딩 목적지', '외부에서 장비의 바깥 주소 `203.0.113.10` 의 **8443** 포트로 들어온 접속은 내부의 어떤 서버·포트로 전달될까요? `/tmp/nat.log` 에서 해당 `DNAT` 규칙의 **`--to-destination` 값**(`주소:포트`)을 `/tmp/fwd.txt` 에 저장하세요. (값만)', '`--dport 8443` 이 들어 있는 줄을 먼저 고르세요.', 'grep ''dport 8443'' /tmp/nat.log | grep -o ''to-destination [0-9.:]*'' | awk ''{print $2}'' > /tmp/fwd.txt
cat /tmp/fwd.txt

# DNAT 는 PREROUTING 에서 목적지를 바꾼다. 바깥 8443 이 내부 서버의 443 으로 가므로 바깥 포트와 내부 포트가 달라도 된다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.conf\\ncat > /tmp/nat.log <<''EOF''\\n-P PREROUTING ACCEPT\\n-P INPUT ACCEPT\\n-P OUTPUT ACCEPT\\n-P POSTROUTING ACCEPT\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 8443 -j DNAT --to-destination 192.0.2.20:443\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 2222 -j DNAT --to-destination 192.0.2.21:22\\n-A POSTROUTING -s 192.0.2.0/24 -o eth0 -j MASQUERADE\\nEOF\\ncat > /tmp/sysctl.log <<''EOF''\\nnet.ipv4.ip_forward = 0\\nnet.ipv4.conf.all.rp_filter = 1\\nEOF\\ncat > /tmp/conn.log <<''EOF''\\ntcp      6 431999 ESTABLISHED src=203.0.113.77 dst=203.0.113.10 sport=51000 dport=8443 src=192.0.2.20 dst=203.0.113.77 sport=443 dport=51000 [ASSURED] mark=0 use=1\\ntcp      6 431998 ESTABLISHED src=203.0.113.88 dst=203.0.113.10 sport=51111 dport=2222 src=192.0.2.21 dst=203.0.113.88 sport=22 dport=51111 [ASSURED] mark=0 use=1\\ntcp      6 118 TIME_WAIT src=192.0.2.30 dst=198.51.100.50 sport=40000 dport=443 src=198.51.100.50 dst=203.0.113.10 sport=443 dport=40000 [ASSURED] mark=0 use=1\\ntcp      6 2 SYN_SENT src=192.0.2.31 dst=198.51.100.60 sport=40001 dport=443 [UNREPLIED] src=198.51.100.60 dst=203.0.113.10 sport=443 dport=40001 mark=0 use=1\\ntcp      6 431990 ESTABLISHED src=192.0.2.32 dst=198.51.100.70 sport=40002 dport=443 src=198.51.100.70 dst=203.0.113.10 sport=443 dport=40002 [ASSURED] mark=0 use=1\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/fwd.txt)\\" = 192.0.2.20:443 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "192.0.2.20:443 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/fwd.txt)\\" = 192.0.2.20:443 ]"]}]', '[{"title": "iptables 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/iptables.8.html"}, {"title": "Netfilter NAT 안내", "url": "https://www.netfilter.org/documentation/HOWTO/NAT-HOWTO.html"}]'),
  (572, 3, '패킷 전달(ip_forward) 값', '`/tmp/sysctl.log` 는 NAT 장비 후보 서버의 `sysctl net.ipv4` 일부입니다. 리눅스는 기본적으로 **자기 앞으로 온 패킷만** 처리하고, 다른 곳으로 전달하려면 `net.ipv4.ip_forward` 가 1 이어야 합니다. 이 서버의 `ip_forward` 값을 `/tmp/fwd_val.txt` 에 저장하세요. (숫자만)', '`=` 뒤의 값입니다. 공백이 섞여 있으니 잘라 낼 때 주의하세요.', 'grep ''^net.ipv4.ip_forward'' /tmp/sysctl.log | awk ''{print $3}'' > /tmp/fwd_val.txt
cat /tmp/fwd_val.txt

# 0 이면 이 서버는 라우터·NAT 장비로 동작하지 못한다. 포트포워딩 규칙이 있어도 패킷이 전달되지 않아 접속이 안 된다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.conf\\ncat > /tmp/nat.log <<''EOF''\\n-P PREROUTING ACCEPT\\n-P INPUT ACCEPT\\n-P OUTPUT ACCEPT\\n-P POSTROUTING ACCEPT\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 8443 -j DNAT --to-destination 192.0.2.20:443\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 2222 -j DNAT --to-destination 192.0.2.21:22\\n-A POSTROUTING -s 192.0.2.0/24 -o eth0 -j MASQUERADE\\nEOF\\ncat > /tmp/sysctl.log <<''EOF''\\nnet.ipv4.ip_forward = 0\\nnet.ipv4.conf.all.rp_filter = 1\\nEOF\\ncat > /tmp/conn.log <<''EOF''\\ntcp      6 431999 ESTABLISHED src=203.0.113.77 dst=203.0.113.10 sport=51000 dport=8443 src=192.0.2.20 dst=203.0.113.77 sport=443 dport=51000 [ASSURED] mark=0 use=1\\ntcp      6 431998 ESTABLISHED src=203.0.113.88 dst=203.0.113.10 sport=51111 dport=2222 src=192.0.2.21 dst=203.0.113.88 sport=22 dport=51111 [ASSURED] mark=0 use=1\\ntcp      6 118 TIME_WAIT src=192.0.2.30 dst=198.51.100.50 sport=40000 dport=443 src=198.51.100.50 dst=203.0.113.10 sport=443 dport=40000 [ASSURED] mark=0 use=1\\ntcp      6 2 SYN_SENT src=192.0.2.31 dst=198.51.100.60 sport=40001 dport=443 [UNREPLIED] src=198.51.100.60 dst=203.0.113.10 sport=443 dport=40001 mark=0 use=1\\ntcp      6 431990 ESTABLISHED src=192.0.2.32 dst=198.51.100.70 sport=40002 dport=443 src=198.51.100.70 dst=203.0.113.10 sport=443 dport=40002 [ASSURED] mark=0 use=1\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/fwd_val.txt)\\" = 0 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "0 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/fwd_val.txt)\\" = 0 ]"]}]', '[{"title": "iptables 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/iptables.8.html"}, {"title": "Netfilter NAT 안내", "url": "https://www.netfilter.org/documentation/HOWTO/NAT-HOWTO.html"}]'),
  (572, 4, '재부팅 후에도 유지되게 설정 적기', '`ip_forward` 를 지금 켜는 것은 `sysctl -w` 로 되지만 재부팅하면 사라집니다. 영구 설정은 `/etc/sysctl.d/` 아래 `.conf` 파일에 `키 = 값` 한 줄로 적습니다. 샌드박스에서는 시스템 설정을 바꿀 수 없으니 **그 파일에 들어갈 한 줄**을 `/tmp/99-forward.conf` 에 적으세요. (`ip_forward` 를 켜는 설정)', '`키 = 값` 한 줄입니다. 켜는 값이 무엇인지는 앞 문제의 `ip_forward` 설명을 떠올려 보세요.', 'echo ''net.ipv4.ip_forward = 1'' > /tmp/99-forward.conf
cat /tmp/99-forward.conf

# 적용은 sysctl --system. 확인은 sysctl net.ipv4.ip_forward 또는 cat /proc/sys/net/ipv4/ip_forward 다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.conf\\ncat > /tmp/nat.log <<''EOF''\\n-P PREROUTING ACCEPT\\n-P INPUT ACCEPT\\n-P OUTPUT ACCEPT\\n-P POSTROUTING ACCEPT\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 8443 -j DNAT --to-destination 192.0.2.20:443\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 2222 -j DNAT --to-destination 192.0.2.21:22\\n-A POSTROUTING -s 192.0.2.0/24 -o eth0 -j MASQUERADE\\nEOF\\ncat > /tmp/sysctl.log <<''EOF''\\nnet.ipv4.ip_forward = 0\\nnet.ipv4.conf.all.rp_filter = 1\\nEOF\\ncat > /tmp/conn.log <<''EOF''\\ntcp      6 431999 ESTABLISHED src=203.0.113.77 dst=203.0.113.10 sport=51000 dport=8443 src=192.0.2.20 dst=203.0.113.77 sport=443 dport=51000 [ASSURED] mark=0 use=1\\ntcp      6 431998 ESTABLISHED src=203.0.113.88 dst=203.0.113.10 sport=51111 dport=2222 src=192.0.2.21 dst=203.0.113.88 sport=22 dport=51111 [ASSURED] mark=0 use=1\\ntcp      6 118 TIME_WAIT src=192.0.2.30 dst=198.51.100.50 sport=40000 dport=443 src=198.51.100.50 dst=203.0.113.10 sport=443 dport=40000 [ASSURED] mark=0 use=1\\ntcp      6 2 SYN_SENT src=192.0.2.31 dst=198.51.100.60 sport=40001 dport=443 [UNREPLIED] src=198.51.100.60 dst=203.0.113.10 sport=443 dport=40001 mark=0 use=1\\ntcp      6 431990 ESTABLISHED src=192.0.2.32 dst=198.51.100.70 sport=40002 dport=443 src=198.51.100.70 dst=203.0.113.10 sport=443 dport=40002 [ASSURED] mark=0 use=1\\nEOF\\ntrue"]', '["sh", "-c", "( grep -Eq \\"^net\\\\.ipv4\\\\.ip_forward[[:space:]]*=[[:space:]]*1[[:space:]]*$\\" /tmp/99-forward.conf )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ip_forward 를 1 로 적었다", "cmd": ["sh", "-c", "grep -Eq \\"^net\\\\.ipv4\\\\.ip_forward[[:space:]]*=[[:space:]]*1[[:space:]]*$\\" /tmp/99-forward.conf"]}]', '[{"title": "iptables 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/iptables.8.html"}, {"title": "Netfilter NAT 안내", "url": "https://www.netfilter.org/documentation/HOWTO/NAT-HOWTO.html"}]'),
  (572, 5, '연결 추적 줄 읽기', '`/tmp/conn.log` 는 `conntrack -L` 로 본 연결 추적 테이블입니다. 한 줄은 **원래 방향**(`src dst sport dport`)과 **응답 방향**(두 번째 `src dst ...`)을 함께 보여 줍니다. 첫 줄은 외부 클라이언트가 포트포워딩된 접속을 한 연결입니다. 이 연결을 **시작한 클라이언트의 주소**(첫 `src=` 값)를 `/tmp/client.txt` 에 저장하세요. (주소만)', '한 줄에 `src=` 가 두 번 나옵니다. 앞의 것이 원래 방향입니다. `grep -o` 로 첫 번째만 뽑으세요.', 'head -1 /tmp/conn.log | grep -o ''src=[0-9.]*'' | head -1 | cut -d= -f2 > /tmp/client.txt
cat /tmp/client.txt

# 응답 방향의 dst 도 같은 클라이언트다. 응답 방향의 src(192.0.2.20)가 실제 내부 서버이고, 원래 방향의 dst(203.0.113.10)는 클라이언트가 접속한 NAT 장비의 바깥 주소다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.conf\\ncat > /tmp/nat.log <<''EOF''\\n-P PREROUTING ACCEPT\\n-P INPUT ACCEPT\\n-P OUTPUT ACCEPT\\n-P POSTROUTING ACCEPT\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 8443 -j DNAT --to-destination 192.0.2.20:443\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 2222 -j DNAT --to-destination 192.0.2.21:22\\n-A POSTROUTING -s 192.0.2.0/24 -o eth0 -j MASQUERADE\\nEOF\\ncat > /tmp/sysctl.log <<''EOF''\\nnet.ipv4.ip_forward = 0\\nnet.ipv4.conf.all.rp_filter = 1\\nEOF\\ncat > /tmp/conn.log <<''EOF''\\ntcp      6 431999 ESTABLISHED src=203.0.113.77 dst=203.0.113.10 sport=51000 dport=8443 src=192.0.2.20 dst=203.0.113.77 sport=443 dport=51000 [ASSURED] mark=0 use=1\\ntcp      6 431998 ESTABLISHED src=203.0.113.88 dst=203.0.113.10 sport=51111 dport=2222 src=192.0.2.21 dst=203.0.113.88 sport=22 dport=51111 [ASSURED] mark=0 use=1\\ntcp      6 118 TIME_WAIT src=192.0.2.30 dst=198.51.100.50 sport=40000 dport=443 src=198.51.100.50 dst=203.0.113.10 sport=443 dport=40000 [ASSURED] mark=0 use=1\\ntcp      6 2 SYN_SENT src=192.0.2.31 dst=198.51.100.60 sport=40001 dport=443 [UNREPLIED] src=198.51.100.60 dst=203.0.113.10 sport=443 dport=40001 mark=0 use=1\\ntcp      6 431990 ESTABLISHED src=192.0.2.32 dst=198.51.100.70 sport=40002 dport=443 src=198.51.100.70 dst=203.0.113.10 sport=443 dport=40002 [ASSURED] mark=0 use=1\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/client.txt)\\" = 203.0.113.77 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "203.0.113.77 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/client.txt)\\" = 203.0.113.77 ]"]}]', '[{"title": "iptables 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/iptables.8.html"}, {"title": "Netfilter NAT 안내", "url": "https://www.netfilter.org/documentation/HOWTO/NAT-HOWTO.html"}]'),
  (572, 6, '연결 상태 집계', '`/tmp/conn.log` 에서 **상태가 `ESTABLISHED` 인 연결이 몇 개**인지 세어 숫자만 `/tmp/est.txt` 에 저장하세요. 연결 추적 테이블이 가득 차는 장애에서는 상태별 개수가 첫 단서가 됩니다.', '특정 단어가 포함된 줄의 개수를 세는 옵션을 찾아 보세요.', 'grep -c ESTABLISHED /tmp/conn.log > /tmp/est.txt
cat /tmp/est.txt

# 3 개. 테이블이 가득 차면 새 연결이 버려진다(nf_conntrack: table full, dropping packet). 개수는 conntrack -C 로 센다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.conf\\ncat > /tmp/nat.log <<''EOF''\\n-P PREROUTING ACCEPT\\n-P INPUT ACCEPT\\n-P OUTPUT ACCEPT\\n-P POSTROUTING ACCEPT\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 8443 -j DNAT --to-destination 192.0.2.20:443\\n-A PREROUTING -d 203.0.113.10/32 -p tcp -m tcp --dport 2222 -j DNAT --to-destination 192.0.2.21:22\\n-A POSTROUTING -s 192.0.2.0/24 -o eth0 -j MASQUERADE\\nEOF\\ncat > /tmp/sysctl.log <<''EOF''\\nnet.ipv4.ip_forward = 0\\nnet.ipv4.conf.all.rp_filter = 1\\nEOF\\ncat > /tmp/conn.log <<''EOF''\\ntcp      6 431999 ESTABLISHED src=203.0.113.77 dst=203.0.113.10 sport=51000 dport=8443 src=192.0.2.20 dst=203.0.113.77 sport=443 dport=51000 [ASSURED] mark=0 use=1\\ntcp      6 431998 ESTABLISHED src=203.0.113.88 dst=203.0.113.10 sport=51111 dport=2222 src=192.0.2.21 dst=203.0.113.88 sport=22 dport=51111 [ASSURED] mark=0 use=1\\ntcp      6 118 TIME_WAIT src=192.0.2.30 dst=198.51.100.50 sport=40000 dport=443 src=198.51.100.50 dst=203.0.113.10 sport=443 dport=40000 [ASSURED] mark=0 use=1\\ntcp      6 2 SYN_SENT src=192.0.2.31 dst=198.51.100.60 sport=40001 dport=443 [UNREPLIED] src=198.51.100.60 dst=203.0.113.10 sport=443 dport=40001 mark=0 use=1\\ntcp      6 431990 ESTABLISHED src=192.0.2.32 dst=198.51.100.70 sport=40002 dport=443 src=198.51.100.70 dst=203.0.113.10 sport=443 dport=40002 [ASSURED] mark=0 use=1\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/est.txt)\\" = 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/est.txt)\\" = 3 ]"]}]', '[{"title": "iptables 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/iptables.8.html"}, {"title": "Netfilter NAT 안내", "url": "https://www.netfilter.org/documentation/HOWTO/NAT-HOWTO.html"}]'),
  (572, 7, '포트포워딩이 안 되는 원인', '외부에서 8443 으로 접속하면 내부 서버(192.0.2.20)의 로그에는 접속이 찍히는데 클라이언트는 응답을 받지 못합니다. 내부 서버의 기본 게이트웨이는 NAT 장비가 아닌 다른 라우터입니다. 가장 알맞은 원인은?', '응답 패킷이 어느 길로 돌아가는지 따라가 보세요.', NULL, NULL, '[]', 'choice', '["NAT 장비가 요청 패킷의 DNAT 규칙을 처리하지 못했다", "내부 서버가 요청 패킷 자체를 받지 못하고 있다", "응답이 NAT 장비를 거치지 않아 주소가 원래대로 되돌려지지 않는다", "클라이언트가 포트 번호를 잘못 알고 있다"]', 2, '요청은 NAT 장비에서 목적지가 변환되어 내부 서버에 도달했습니다(서버 로그에 찍힘). 그런데 응답이 다른 게이트웨이로 나가면 출발지가 내부 주소 그대로라 클라이언트가 모르는 주소의 응답으로 버립니다. 내부 서버의 게이트웨이를 NAT 장비로 하거나 출발지도 함께 변환(SNAT·MASQUERADE)해야 합니다.', NULL, NULL, NULL, NULL),
  (572, 8, 'PREROUTING 과 POSTROUTING', '`DNAT` 규칙은 PREROUTING 체인에, `MASQUERADE` 규칙은 POSTROUTING 체인에 둡니다. 이렇게 나뉘는 이유로 가장 알맞은 것은?', '라우팅 결정이 패킷 경로의 어느 지점에서 일어나는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["두 체인은 처리 속도 때문에 번갈아 쓰는 것이다", "목적지는 라우팅 결정 전에, 출발지는 나가기 직전에 바꾸기 때문이다", "출발지 변환은 들어오는 패킷에만 적용되기 때문이다", "두 규칙은 같은 체인에 둘 수 없는 규칙이라서다"]', 1, '목적지를 바꾸면 그 결과로 어디로 보낼지(라우팅)가 달라지므로 라우팅 결정 전인 PREROUTING 에서 바꿉니다. 출발지는 나가는 인터페이스가 정해진 뒤 나가기 직전인 POSTROUTING 에서 바꾸는 것이 자연스럽습니다.', NULL, NULL, NULL, NULL),
  (572, 9, 'MASQUERADE 를 두는 체인', '내부망(192.0.2.0/24)이 바깥 인터페이스 `eth0` 로 나갈 때 출발지를 장비 주소로 바꾸는 규칙입니다. 빈칸에 들어갈 체인 이름을 채우세요.', '패킷이 나가기 직전에 거치는 체인입니다.', NULL, NULL, '[]', 'fill', '["POSTROUTING", "PREROUTING", "INPUT", "FORWARD"]', NULL, '`-o eth0`(나가는 인터페이스)는 라우팅이 끝난 뒤에야 정해지므로 PREROUTING 에서는 쓸 수 없고, MASQUERADE 는 POSTROUTING 에서만 쓸 수 있는 타깃입니다. INPUT 은 장비 자신에게 오는 패킷용, FORWARD 는 nat 테이블에 없는 체인입니다.', '[0]', 'iptables -t nat -A {0} -s 192.0.2.0/24 -o eth0 -j MASQUERADE', NULL, NULL),
  (572, 10, '포트포워딩된 패킷의 이동 순서', '외부 클라이언트가 NAT 장비의 바깥 주소로 보낸 패킷이 내부 서버에 도착하기까지 장비 안에서 거치는 처리를 순서대로 놓으세요.', '주소를 바꾸는 시점과 허용 여부를 판단하는 시점의 선후를 생각해 보세요.', NULL, NULL, '[]', 'order', '["PREROUTING 에서 목적지 주소를 변환한다(DNAT)", "FORWARD 체인에서 허용 여부를 판단한다", "POSTROUTING 에서 필요하면 출발지를 변환한다", "패킷이 NAT 장비의 바깥 인터페이스로 도착한다"]', NULL, '들어온 패킷은 먼저 PREROUTING 에서 목적지가 변환되고, 새 목적지를 보고 라우팅 결정이 내려져 FORWARD 에서 허용 여부를 따진 뒤, 나가기 직전 POSTROUTING 에서 출발지 변환이 필요하면 적용됩니다.', '[3, 0, 1, 2]', NULL, NULL, NULL);
